import{z as o,x as i,o as B,c as d,q as A,j as r,D as s,d as a,s as l,S as t,b as e}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"内存安全语言","description":"","frontmatter":{"title":"内存安全语言","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ss-memory-safe-langs.md","filePath":"cs/ss-memory-safe-langs.md","lastUpdated":1791063341000}'),u={name:"cs/ss-memory-safe-langs.md"};function f(C,E,m,D,p,F){const n=i("Mermaid");return B(),d("div",null,[E[2]||(E[2]=A('<h1 id="内存安全语言" tabindex="-1">内存安全语言 <a class="header-anchor" href="#内存安全语言" aria-label="Permalink to &quot;内存安全语言&quot;">​</a></h1><div class="epigraph"><p>安全语言把内存错误从「运行时碰运气」改成「编译时证不出来就编译不过」；代价是把审计对象从每一次内存访问，换成类型系统本身与它的 unsafe 缝隙。</p><footer>—— 据 Jung et al., RustBelt, POPL 2018；Google Android 安全博客（2022）整理</footer></div><p><a href="/cs/ss-fuzzing-deep">上一课</a>给了「bug 从哪来」的自动发现路线；发现之后，根治路线之一是换掉产生 bug 的语言合同。主干在<a href="/cs/memory-safe-languages">内存安全语言</a>钉了立场——PAC/CET 是缓解，安全语言改语义，FFI 与运行时仍是 TCB；<a href="/cs/rust-in-kernel">Rust 进内核</a>给了工程路径。本课深钻「安全」二字靠什么成立：类型系统的保证如何构造、覆盖<a href="/cs/ss-kernel-vuln-classes">内核漏洞类别</a>表的哪几格、漏掉哪几格。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>先看规模：微软 MSRC 与 Chromium 各自的口径下，严重 CVE 里内存安全问题约占七成——类别表里空间、时间、未初始化、整数四类正是这份大头。C 的类型系统表达不出「这个指针在有效期内且无别名可写」，于是这两条性质只能靠运行时纪律维持，而纪律会被并发与重构磨穿。缺口是：安全语言的保证究竟怎么构造、构造到什么强度、证据是什么——而不是重申「Rust 好」。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="所有权、unsafe-与运行时托管" tabindex="-1">所有权、unsafe 与运行时托管 <a class="header-anchor" href="#所有权、unsafe-与运行时托管" aria-label="Permalink to &quot;所有权、unsafe 与运行时托管&quot;">​</a></h3><p>Rust 的构造是三条规则：每个值唯一所有（仿射类型，绑定即移动）；借用检查器证「可变与别名互斥」；生命周期把「引用不活得比所有者久」变成编译期事实。悬垂与双重释放属于时间类，在编译期被证掉；数组边界检查在运行时兜住空间类；未初始化类由默认零化与初始化检查兜住。证不到的地方不撒谎：<code>unsafe</code> 块把「机器证不了、由人担保」的代码显式圈出来，审计面从全部代码收缩到 unsafe 与 FFI 边界。RustBelt 进一步把这个「safe 的含义」做成机器检查的证明：只要 unsafe 边界守约，safe 子集整体类型安全。GC 语言走另一条路：空间与时间安全由托管运行时给，代价是运行时与 JIT 自身成为新的 TCB——它们一旦有洞，所有人的保证同时漏。</p><p><span class="marginnote">Android 的实测：内存安全漏洞占比从 2019 年的 76% 降到 2022 年的 35%——没有重写存量，只是新代码改用 Rust 与 Kotlin，占比随替换自然下降。据 Google 安全博客 Memory Safe Languages in Android 13 整理。</span></p><p><span class="marginnote">「唯一所有」翻译成大白话：赋值即过户——把结构体传给别人后，你手里那份就作废了，再用直接编译报错。借用检查则像图书馆规则：同一本书要么多人同时读（不可变借用），要么借给一个人独占修改（可变借用），两件事不能同时发生。初学者最常撞上的墙就是这条，但它挡住的正是并发改写共享数据的整类 bug。</span></p>',10)),(B(),r(t,null,{default:s(()=>[l(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TBL%5B%22%E7%AC%AC%201%20%E8%AF%BE%E7%B1%BB%E5%88%AB%EF%BC%9A%E7%A9%BA%E9%97%B4%20%2F%20%E6%97%B6%E9%97%B4%20%2F%20%E6%9C%AA%E5%88%9D%E5%A7%8B%E5%8C%96%20%2F%20%E6%95%B4%E6%95%B0%20%2F%20%E9%80%BB%E8%BE%91%22%5D%20--%3E%20CK%5B%22%E7%BC%96%E8%AF%91%E6%9C%9F%EF%BC%9A%E6%89%80%E6%9C%89%E6%9D%83%E4%B8%8E%E5%80%9F%E7%94%A8%E6%A3%80%E6%9F%A5%22%5D%0A%20%20TBL%20--%3E%20RT%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%EF%BC%9A%E8%BE%B9%E7%95%8C%E6%A3%80%E6%9F%A5%20%2F%20%E9%9B%B6%E5%8C%96%22%5D%0A%20%20TBL%20--%3E%20NO%5B%22%E8%AF%81%E4%B8%8D%E5%88%B0%EF%BC%9Aunsafe%20%E4%B8%8E%20FFI%20%E7%94%B1%E4%BA%BA%E6%8B%85%E4%BF%9D%22%5D%0A%20%20TBL%20--%3E%20OUT%5B%22%E8%AF%AD%E8%A8%80%E4%B9%8B%E5%A4%96%EF%BC%9A%E9%80%BB%E8%BE%91%E4%B8%8E%E6%9D%83%E9%99%90%E7%B1%BB%22%5D%0A%20%20CK%20--%3E%20OK%5B%22%E5%AE%89%E5%85%A8%E5%AD%90%E9%9B%86%E6%88%90%E7%AB%8B%22%5D%0A%20%20RT%20--%3E%20OK%0A%20%20NO%20--%3E%20AUD%5B%22%E5%AE%A1%E8%AE%A1%E9%9D%A2%E6%94%B6%E7%BC%A9%E5%88%B0%20unsafe%20%E8%BE%B9%E7%95%8C%22%5D%0A"})]),fallback:s(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("把保证的边界讲清楚：类型安全不等于程序安全。逻辑类与权限类语言管不着——缺一次权限检查在 Rust 里照样能写；整数类只挡回绕导致的内存后果，数值算错照旧。并发是个分界线：Rust 把数据竞争变成类型错误（"),e("code",null,"Send"),a("/"),e("code",null,"Sync"),a(" 标记），死锁与竞态逻辑仍然可能。迁移的机制因此不是重写，而是攻击面排序：把解析不可信输入的模块先换——新代码安全语言、旧代码靠缓解与 fuzzing 顶住，占比随替换率下降，Android 的曲线就是这个机制的实测结果。")],-1)),(B(),r(t,null,{default:s(()=>[l(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20LEGACY%5B%22%E5%AD%98%E9%87%8F%20C%2FC%2B%2B%20%E4%BB%A3%E7%A0%81%E5%BA%93%22%5D%20--%3E%20RANK%5B%22%E6%8C%89%E6%94%BB%E5%87%BB%E9%9D%A2%E6%8E%92%E5%BA%8F%22%5D%0A%20%20RANK%20--%3E%20HI%5B%22%E9%AB%98%E6%94%BB%E5%87%BB%E9%9D%A2%EF%BC%9A%E8%A7%A3%E6%9E%90%E4%B8%8D%E5%8F%AF%E4%BF%A1%E8%BE%93%E5%85%A5%22%5D%20--%3E%20REWRITE%5B%22%E4%BC%98%E5%85%88%E7%94%A8%E5%AE%89%E5%85%A8%E8%AF%AD%E8%A8%80%E9%87%8D%E5%86%99%22%5D%0A%20%20RANK%20--%3E%20LO%5B%22%E4%BD%8E%E6%94%BB%E5%87%BB%E9%9D%A2%EF%BC%9A%E5%86%85%E9%83%A8%E6%95%B0%E6%8D%AE%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20HOLD%5B%22%E7%BC%93%E8%A7%A3%E4%B8%8E%20fuzzing%20%E9%A1%B6%E4%BD%8F%22%5D%0A%20%20REWRITE%20--%3E%20DROP%5B%22%E5%86%85%E5%AD%98%E6%BC%8F%E6%B4%9E%E5%8D%A0%E6%AF%94%E9%9A%8F%E6%9B%BF%E6%8D%A2%E4%B8%8B%E9%99%8D%22%5D%0A%20%20HOLD%20--%3E%20FREEZE%5B%22%E8%AF%A5%E8%B7%AF%E5%BE%84%E4%B8%8D%E5%86%8D%E6%96%B0%E5%A2%9E%E5%90%8C%E7%B1%BB%E6%BC%8F%E6%B4%9E%22%5D%0A"})]),fallback:s(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=A('<p><span class="marginnote">迁移的真实路径是「新代码先安全」而不是「推倒重写」：攻击者只能打进暴露面，所以先换解析网络输入、文件格式的模块，收益最大。误区是以为要等存量全部重写才有安全感——Android 的 76% 降到 35% 靠的正是新代码占比逐年升高这一条曲线。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>「safe 子集安全」依赖 unsafe 守约与标准库正确——这两者是显式 TCB，不是无限担保；Rust 进内核的构建与 ABI 工程专课已讲，不重写；供应链问题（安全语言项目照样会被投毒）归供应链课。C++ 的安全子集与硬化路线只在对照时点名，不展开。</p><p><span class="marginnote">常见误区：以为换成内存安全语言就「没有 bug」了。证掉的只是空间/时间/未初始化这几格，密码比对写成非常量时间、权限检查漏写一次、业务逻辑算错钱——这些 Rust 一个都不会拦。所以安全语言的正确读法是「把某几类错误从可能变不可能」，而不是「安全」二字的无限担保。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>七成严重 CVE 是内存安全；空间/时间/未初始化/整数四类构成大头，正是类型系统能表达的部分。</li><li>Rust 的构造：唯一所有权、可变与别名互斥、生命周期检查；边界检查与零化运行时兜底。</li><li>unsafe 是显式 TCB；RustBelt 把「safe 的含义」做成机器检查证明。</li><li>语言不覆盖逻辑与权限类；数据竞争变类型错误，死锁仍可能。</li><li>迁移是攻击面排序加替换率：Android 从 76% 降到 35% 是实测曲线。</li><li>出处：Jung et al., POPL 2018；Google 安全博客 2022；对照 <a href="/cs/memory-safe-languages">memory-safe-langs</a>、<a href="/cs/rust-in-kernel">rust-in-kernel</a>。</li></ul>',6))])}const g=o(u,[["render",f]]);export{h as __pageData,g as default};
